{
  "id": 25,
  "knowledge": "Functional Impairment",
  "description": "Illustrates the value of functional impairment levels.",
  "definition": "Ranges from Mild to Severe. Mild indicates minimal impact on daily life, Moderate indicates noticeable impact, and Severe indicates significant disruption."
}

{
  "id": 6,
  "knowledge": "Patient Functional Impairment Score (PFIS)",
  "description": "Calculates an average functional impairment score across patients.",
  "definition": "PFIS = \text{The average of functional impairment scores, where the score is 3 for 'Severe' impairment, 2 for 'Moderate', and 1 for 'Mild'.}"
}

{
  "id": 24,
  "knowledge": "Community Resources",
  "description": "Illustrates the value of community resource availability.",
  "definition": "Ranges from Limited to Comprehensive/Extensive. Limited indicates few resources, Adequate indicates sufficient resources, and Comprehensive/Extensive indicates robust resources."
}

{
  "id": 22,
  "knowledge": "Suicide Risk Level",
  "description": "Illustrates the value of the suicide risk level.",
  "definition": "Ranges from Low to High. Low indicates minimal risk, Medium indicates some concern, and High indicates immediate concern and need for intervention."
}

{
  "id": 10,
  "knowledge": "High-Risk Patient",
  "description": "Identifies patients with elevated suicide risk or severe symptoms.",
  "definition": "A patient whose assessed suicide risk is 'High', or whose depression score (PHQ-9) is over 15, or whose anxiety score (GAD-7) is over 15."
}

{
  "id": 3,
  "knowledge": "Suicide Risk Prevalence (SRP)",
  "description": "Calculates the percentage of assessments indicating high or severe suicide risk at a facility.",
  "definition": "SRP = \frac{\text{Number of assessments with a 'High' suicide risk}}{\text{Total number of assessments}} \times 100 \text{ for a given facility.}"
}
